<script setup lang="ts">
const api=useApi(); const { data: users, refresh }=await useAsyncData('admin-users',()=>api.request<any[]>('/admin/users').catch(()=>[]))
async function update(id:string,body:any){await api.request(`/admin/users/${id}`,{method:'POST',body});await refresh()}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Access</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Users & roles.</h1><p class="mt-1 text-[11.5px] text-ink/45">Tenant members, permissions and account status.</p></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">User</th><th class="px-4 py-2.5">Role</th><th class="px-4 py-2.5">Status</th><th class="px-4 py-2.5">Last login</th></tr></thead><tbody><tr v-for="u in users" :key="u._id" class="border-t border-ink/10"><td class="px-4 py-3"><p class="font-medium">{{ u.name }}</p><p class="font-mono text-[8px] text-ink/30">{{ u.email }}</p></td><td class="px-4 py-3"><AppSelect :model-value="u.role" :options="['owner','admin','engineer','contractor','homeowner','manufacturer']" compact aria-label="User role" @update:model-value="v => update(u._id,{role:v,active:u.active})" /></td><td class="px-4 py-3"><button class="font-mono text-[8px] uppercase" :class="u.active?'text-mint-deep':'text-signal-deep'" @click="update(u._id,{role:u.role,active:!u.active})">{{ u.active ? 'Active' : 'Disabled' }}</button></td><td class="px-4 py-3 text-ink/40">{{ shortDate(u.lastLoginAt) }}</td></tr></tbody></table></div></div></template>
